import{_ as s,C as i,o as l,c as o,j as e,a as n,E as r,a5 as d}from"./chunks/framework.-jms6n7v.js";const b=JSON.parse('{"title":"성능","description":"DaruDB가 각 언어에서 가장 많이 쓰는 임베디드 데이터베이스와 비교해 얼마나 빨리 읽고 쓰는지, 저장소에 있는 벤치마크로 잰 결과입니다. 모든 데이터베이스에서 같은 객체와 같은 작업을 같은 내구성 설정으로 한 기계에서 실행했습니다.","frontmatter":{"title":"성능","order":3,"aside":false,"pageClass":"performance-page","prev":{"text":"다른 DB와 비교","link":"/ko/compare"},"next":{"text":"다른 DB에서 옮기기","link":"/ko/migration/"}},"headers":[{"level":2,"title":"무엇을 재는가","slug":"무엇을-재는가","link":"#무엇을-재는가","children":[]},{"level":2,"title":"공정하게 재는 방법","slug":"공정하게-재는-방법","link":"#공정하게-재는-방법","children":[]},{"level":2,"title":"Realm과 견주면","slug":"realm과-견주면","link":"#realm과-견주면","children":[]},{"level":2,"title":"DaruDB가 뒤지는 곳과 이유","slug":"darudb가-뒤지는-곳과-이유","link":"#darudb가-뒤지는-곳과-이유","children":[]},{"level":2,"title":"복잡한 스위트","slug":"복잡한-스위트","link":"#복잡한-스위트","children":[{"level":3,"title":"이 스위트가 재는 것","slug":"이-스위트가-재는-것","link":"#이-스위트가-재는-것","children":[]},{"level":3,"title":"복잡한 스위트에서 DaruDB가 뒤지는 곳과 이유","slug":"복잡한-스위트에서-darudb가-뒤지는-곳과-이유","link":"#복잡한-스위트에서-darudb가-뒤지는-곳과-이유","children":[]}]},{"level":2,"title":"직접 실행하기","slug":"직접-실행하기","link":"#직접-실행하기","children":[]}],"relativePath":"ko/performance.md","filePath":"ko/performance.md","lastUpdated":1793191173000}'),D={name:"ko/performance.md"};function h(u,t,p,c,B,m){const a=i("PerformanceTable");return l(),o("div",null,[t[0]||(t[0]=e("h1",{id:"성능",tabindex:"-1"},[n("성능 "),e("a",{class:"header-anchor",href:"#성능","aria-label":'Permalink to "성능"'},"​")],-1)),t[1]||(t[1]=e("p",null,"DaruDB가 각 언어에서 가장 많이 쓰는 임베디드 데이터베이스와 비교해 얼마나 빨리 읽고 쓰는지, 저장소에 있는 벤치마크로 잰 결과입니다. 모든 데이터베이스에서 같은 객체와 같은 작업을 같은 내구성 설정으로 한 기계에서 실행했습니다.",-1)),t[2]||(t[2]=e("p",null,"표는 사이드바에서 고른 언어를 따릅니다. 한 언어의 저장소들은 한 기계에서 차례로 실행했으므로 서로 비교할 수 있지만, 언어가 다른 표는 다른 실행에서 나왔으므로 서로 비교하지 않습니다.",-1)),r(a),t[3]||(t[3]=d('<h2 id="무엇을-재는가" tabindex="-1">무엇을 재는가 <a class="header-anchor" href="#무엇을-재는가" aria-label="Permalink to &quot;무엇을 재는가&quot;">​</a></h2><p>객체 100,000개가 든 컬렉션 하나를 씁니다. 객체마다 이름, 고유 인덱스가 걸린 이메일, 인덱스가 걸린 나이, 인덱스 없는 도시와 점수가 있습니다. 행마다 작업을 여러 번 실행한 시간을 작업 수로 나눕니다.</p><table tabindex="0"><thead><tr><th>작업</th><th>하는 일</th></tr></thead><tbody><tr><td>삽입, 동기 커밋마다 객체 하나</td><td>객체 하나씩 커밋 500번, 커밋마다 디스크를 기다립니다</td></tr><tr><td>삽입, 지연 커밋마다 객체 하나</td><td>객체 하나씩 커밋 10,000번, 동기화는 나중으로 미룹니다</td></tr><tr><td>트랜잭션 하나로 객체 100,000개 삽입</td><td>모든 객체를 넣고 커밋까지 합니다</td></tr><tr><td>기본 키로 읽기, 무작위 순서</td><td>객체 하나 읽기 100,000번</td></tr><tr><td>고유 인덱스로 읽기, 무작위 순서</td><td>이메일로 객체 하나 읽기 20,000번</td></tr><tr><td>인덱스 값 쿼리, 객체 1,250개</td><td>나이 하나에 속한 객체</td></tr><tr><td>인덱스 범위 쿼리, 정렬 후 20개</td><td>나이 다섯 개에 속한 객체를 나이 내림차순, 그다음 키 순으로 정렬한 첫 20개</td></tr><tr><td>인덱스로 개수 세기</td><td>나이가 40 이상인 객체</td></tr><tr><td>인덱스 없는 쿼리, 객체 1,000개</td><td>도시 하나에 속한 객체, 열 번</td></tr><tr><td>인덱스 없는 쿼리, 객체 1,000개, 처음 실행</td><td>그 열 번 가운데 처음</td></tr><tr><td>인덱스 없는 필드로 상위 10개</td><td>점수가 가장 높은 객체 10개, 열 번</td></tr><tr><td>인덱스 없는 필드로 상위 10개, 처음 실행</td><td>그 열 번 가운데 처음</td></tr><tr><td>객체 10,000개 읽고 고치기</td><td>객체마다 읽어서 나이를 바꿔 다시 쓰고, 트랜잭션 하나로 커밋까지 합니다</td></tr><tr><td>객체 10,000개 지우기</td><td>트랜잭션 하나로 커밋까지 합니다</td></tr></tbody></table><p>인덱스 없는 쿼리 두 개는 처음 실행을 따로 한 행으로 둡니다. DaruDB는 이런 쿼리를 한 번 실행한 뒤로는 더 빨리 답하기 때문입니다. 검사하거나 정렬하는 필드가 레코드마다 어디 있는지 기억해 두었다가 다음 실행에서 그 자리를 바로 읽습니다. 애플리케이션이 한 번만 실행하는 쿼리라면 처음 실행 행의 시간이 걸립니다.</p><p>데이터베이스는 저마다 그 언어의 애플리케이션이 쓰는 방식대로 씁니다. DaruDB는 스키마와 함께 공개 API로, SQLite는 준비한 문장으로 SQL을 쓰고, 키-값 저장소는 애플리케이션이 직접 만들 법한 레코드와 인덱스를 둡니다. 읽은 결과는 모두 필드를 빠짐없이 가진 그 언어의 객체로 만들고, 여러 번 도는 쿼리는 한 번만 준비합니다. 필드 하나를 고칠 때는 SQL이 열 하나만 바꾸듯, 그 언어의 DaruDB 패키지가 허락하면 바뀌는 필드만 씁니다. Node.js, Python, Dart에서는 객체 전체를 다시 쓰려면 그 언어에서 객체를 새로 만들어야 하므로 <code>update</code>를 쓰고, Rust에서는 타입으로 필드를 가리키는 <code>TypedWriter::set</code>을 씁니다.</p><p>Node.js와 Dart 표에는 Realm에서 옮기려는 애플리케이션을 위해 Realm도 넣었습니다. Realm은 2024년 9월에 공급사가 지원 중단을 알렸고 2025년 9월에 지원이 끝났습니다. 데이터를 옮기는 방법은 <a href="./migration/realm">마이그레이션 가이드</a>에 있습니다. Realm은 키를 정해 주지 않으므로 애플리케이션이 다른 저장소와 같은 키를 객체마다 줍니다. 기본 키 말고는 고유 인덱스가 없어서 이메일에는 일반 인덱스를 걸었고, 준비해 둔 쿼리가 없어서 쿼리 문자열을 호출할 때마다 해석합니다. 고칠 때는 속성 하나만 바꿉니다.</p><h2 id="공정하게-재는-방법" tabindex="-1">공정하게 재는 방법 <a class="header-anchor" href="#공정하게-재는-방법" aria-label="Permalink to &quot;공정하게 재는 방법&quot;">​</a></h2><ul><li><strong>같은 내구성.</strong> 동기 커밋은 디스크가 커밋을 받을 때까지 기다립니다. DaruDB의 기본 커밋, <code>synchronous = FULL</code>인 SQLite의 WAL, LMDB의 기본 커밋, redb의 <code>Durability::Immediate</code>, Hive의 쓰기 뒤 <code>flush</code>, Realm의 커밋이 이에 해당합니다. 지연 커밋은 그 전에 반환합니다. DaruDB의 지연 커밋, <code>synchronous = NORMAL</code>, LMDB의 <code>NO_SYNC</code>, redb의 <code>Durability::None</code>, <code>flush</code> 없는 Hive의 쓰기입니다. Realm에는 동기화를 뒤로 미루는 커밋이 없어서 그 행의 Realm 칸은 비어 있습니다. redb의 지연 커밋은 나중에 즉시 커밋을 하기 전까지 아무것도 영속되지 않으므로 다른 것보다 약속이 약합니다.</li><li><strong>같은 일.</strong> 행마다 찾은 객체의 키와 나이를 찾은 순서대로 해시합니다. 두 데이터베이스의 결과가 다르면 시간을 내지 않고 실행을 실패로 끝냅니다.</li><li><strong>깨끗한 시작.</strong> 데이터베이스마다 한 번의 실행은 자기 프로세스에서 새 파일로 하고, 데이터베이스가 도는 순서는 실행마다 바뀝니다. 시간은 여러 실행의 중앙값입니다.</li><li><strong>같은 기계.</strong> 한 언어의 데이터베이스는 한 기계에서 차례로 실행합니다.</li></ul><p>데이터베이스가 쓰는 캐시는 기본값 그대로 두되, SQLite만 DaruDB와 같은 32 MiB로 올렸습니다. Hive처럼 모든 객체를 메모리에 두는 데이터베이스는 파일을 건드리지 않고 읽습니다.</p><p>표의 결과는 <code>run-benchmarks</code> 워크플로가 언어마다 GitHub 호스트 Linux 러너를 하나씩 받아 잰 것입니다. 이 러너들은 쓰기 배리어 없이 디스크를 마운트하므로, 거기서 동기 커밋은 파일 시스템의 일은 기다리지만 디스크 자체의 캐시는 기다리지 않습니다. 러너의 프로세서와 디스크도 실행마다 달라지고, 커밋 행이 그에 따라 가장 크게 움직입니다. 같은 날 같은 코드로 Node.js에서 객체 하나를 지연 커밋하는 데, 한 실행의 EPYC 9V45 러너에서는 SQLite가 53 µs, DaruDB가 25 µs 걸렸고, 다음 실행의 EPYC 7763 러너에서는 33 µs와 46 µs가 걸렸습니다. 그 이유는 다음 절에 있습니다. 커밋 행은 한 표 안에서만 비교하세요.</p><h2 id="realm과-견주면" tabindex="-1">Realm과 견주면 <a class="header-anchor" href="#realm과-견주면" aria-label="Permalink to &quot;Realm과 견주면&quot;">​</a></h2><p>Realm에서 옮기려는 애플리케이션이라면 Node.js와 Dart 표를 보면 됩니다. 사이드바에서 Node.js나 Dart를 고르면 보입니다. DaruDB는 인덱스 없는 필드인 도시 하나로 찾는 쿼리의 처음 실행을 빼고, Dart에서는 고치기도 빼고 모든 행에서 Realm을 앞섭니다. Realm은 속성마다 값을 모아 두므로 도시 값만 읽고, 처음 실행에는 Node.js에서 DaruDB 시간의 0.69배, Dart에서 0.73배가 걸립니다. 열 번을 실행하면 1.04배와 1.10배가 걸립니다. DaruDB는 두 번째 실행부터 처음 실행이 레코드마다 찾아 둔 자리에서 도시를 바로 읽기 때문입니다. Node.js와 Dart에서 Realm은 동기 커밋에 각각 2.2배와 3.2배가 걸리고 지연 커밋은 없으며, 트랜잭션 하나로 객체 100,000개를 넣는 데 6.4배와 3.4배, 10,000개를 지우는 데 6.3배와 2.2배가 걸립니다. 키로 읽는 데는 3.8배와 2.5배, 이메일로 찾는 데는 13배와 7.3배가 걸립니다. 호출할 때마다 쿼리 문자열을 해석하고, 기본 키 말고는 고유 인덱스가 없기 때문입니다. 나이 하나에 속한 객체를 찾는 데는 4.6배와 3.8배, 나이 다섯 개에서 정렬한 첫 20개를 찾는 데는 112배와 98배가 걸립니다. 다섯 나이의 객체를 모두 정렬한 다음에야 첫 20개를 고르기 때문입니다. 점수가 가장 높은 객체 10개를 찾는 데는 2.4~3.7배가 걸립니다. 고치기는 둘 다 필드 하나만 바꾸며, Realm이 Node.js에서 DaruDB 시간의 1.11배, Dart에서 0.50배가 걸립니다.</p><h2 id="darudb가-뒤지는-곳과-이유" tabindex="-1">DaruDB가 뒤지는 곳과 이유 <a class="header-anchor" href="#darudb가-뒤지는-곳과-이유" aria-label="Permalink to &quot;DaruDB가 뒤지는 곳과 이유&quot;">​</a></h2><p>이번에는 Rust, Dart, Python이 AMD EPYC 9V45, Node.js가 AMD EPYC 7763 프로세서의 러너에서 돌았습니다. DaruDB는 Node.js, Dart, Python에서 대부분의 행을 다른 모든 데이터베이스보다 앞서고, Python에서는 인덱스 없는 쿼리의 처음 실행 두 행을 빼고 모든 행에서 SQLite를 앞섭니다. Dart에서는 키로 읽기와 인덱스 없는 쿼리를 빼고 모든 행에서 앞서는데, 그 두 곳에서는 모든 객체를 메모리에 두는 Hive가 앞서고, 고치기에서는 Realm이 앞섭니다. Rust에서는 지연 커밋, 읽기, 개수 세기를 뺀 쿼리에서 LMDB가 앞서고, 나이 인덱스를 쓰는 쿼리와 인덱스 없는 쿼리의 처음 실행에서는 redb와 SQLite도 앞섭니다. DaruDB가 앞서지 못하는 행과 그 이유는 아래와 같습니다.</p><ul><li><strong>객체 하나를 지연 커밋할 때.</strong> LMDB가 실행되는 모든 언어에서 DaruDB 시간의 0.36~0.51배로 앞서고, Rust에서는 redb가 0.72배, Node.js에서는 SQLite가 0.73배로 앞섭니다. Linux에서 DaruDB의 커밋은 절반쯤을 커널에서 보냅니다. 시스템 호출이 열네 번쯤인데, 열한 개 남짓한 페이지를 쓰는 쓰기가 열 번이고, 나머지 네 번은 쓰기 잠금을 얻고 놓는 호출과 다른 쓰기 프로세스와 읽기 프로세스가 있는지 확인하는 호출입니다. 프로세스끼리 파일 잠금만으로 조율하기 때문입니다. LMDB는 쓰기 일곱 번이면 되고, 프로세스를 공유 메모리의 뮤텍스로 조율합니다. DaruDB는 이 방식을 쓰지 않습니다. 뮤텍스를 쥔 프로세스가 죽으면 나머지가 멈춰 설 수 있기 때문입니다. SQLite의 지연 커밋은 커밋만으로 끝나지 않습니다. 로그가 천 페이지 찰 때마다 체크포인트를 하며 로그와 파일을 동기화하는데, 대부분의 러너에서 SQLite의 지연 커밋은 시간의 3분의 2 이상을 이 동기화를 기다리며 보냈습니다. EPYC 7763 러너는 이 동기화를 더 빨리 끝내고, 러너 기종 가운데 가장 오래된 그 프로세서는 아무것도 기다리지 않는 DaruDB의 커밋을 가장 느리게 처리합니다. EPYC 9V45 러너에서 돈 Rust, Dart, Python에서는 DaruDB의 지연 커밋이 SQLite 시간의 0.42~0.44배가 걸렸습니다.</li><li><strong>동기 커밋</strong>은 다른 어떤 행보다 러너에 따라 크게 달라집니다. 이번에는 EPYC 7763 러너에서 돈 Node.js에서 SQLite가 DaruDB 시간의 0.85배로 앞서고, EPYC 9V45 러너에서 돈 Rust, Dart, Python에서는 DaruDB가 다른 모든 데이터베이스를 앞섭니다. 러너에서 동기 커밋은 대부분 파일 시스템의 일입니다. DaruDB는 커밋의 페이지를 빈 페이지가 있는 곳, 곧 파일 곳곳에 흩어 쓰는데, SQLite는 로그 끝에 이어서 씁니다. 디스크만 따로 잰 시험에서 EPYC 7763 러너는 파일 곳곳에 흩어 쓴 12쪽을 동기화하는 데, 같은 12쪽을 한곳에 이어 쓴 것보다 세 배가 걸렸습니다.</li><li><strong>Rust에서 읽기와 인덱스를 쓰는 쿼리.</strong> 키로 객체를 찾는 데 LMDB는 DaruDB 시간의 0.68배, redb는 0.83배가 걸리고, 이메일로 찾는 데 LMDB는 0.72배가 걸립니다. 나이 인덱스를 쓰는 쿼리는 LMDB, redb, SQLite가 0.48~0.82배에 끝냅니다. DaruDB의 조회는 루트 아래로 거치는 페이지마다 페이지 캐시에서 잠금을 잡고 참조 수를 세어 페이지를 찾고, 노드 안에서 키를 바이트로 비교해 탐색한 다음, 필드마다 id를 붙인 레코드를 구조체로 디코딩합니다. 페이지 캐시에서 찾는 일이 조회에서 차지하는 몫은 이 x86 프로세서에서 Apple 프로세서보다 큽니다. LMDB는 파일을 메모리에 매핑해 읽으므로 찾아볼 캐시가 없고, redb는 기본 키를 정수로 비교하며, 둘 다 필드를 정해진 자리에 둔 직접 짠 레코드를 읽습니다. DaruDB가 파일을 매핑하지 않는 까닭은 매핑한 바이트를 다른 프로세스가 읽는 도중에 바꿀 수 있고, 매핑은 암호화와 함께 쓸 수 없기 때문입니다. 정렬한 범위 읽기는 비용이 더 듭니다. 이 쿼리는 나이 내림차순, 그다음 키 순으로 정렬하므로 DaruDB는 나이 인덱스를 거꾸로 훑으며 나이마다 객체를 붙잡아 두었다가 키 순으로 내놓는데, 키-값 저장소용으로 짠 반복문은 나이를 하나씩 차례로 요청합니다. Apple M1 Max에서는 정렬한 범위 읽기를 빼고 이 행들 모두 DaruDB가 LMDB를 앞섰습니다.</li><li><strong>Dart에서 키로 읽을 때</strong>는 Hive가 DaruDB 시간의 0.90배로 앞섭니다. Hive는 박스의 모든 객체를 메모리에 두고 쥐고 있는 객체를 그대로 내주지만, DaruDB는 페이지 캐시를 거쳐 트리에서 레코드를 찾고 그 레코드로 객체를 만듭니다.</li><li><strong>인덱스 없는 쿼리.</strong> Rust의 LMDB가 2.6~7.1배, Dart의 Hive가 1.1~2.4배 빨리 훑고, Realm은 Node.js와 Dart 모두에서 도시 하나의 객체를 처음 실행에서 더 빨리 찾습니다. SQLite와 redb는 처음 실행에서만 앞섭니다. SQLite는 Rust, Node.js, Dart, Python에서 DaruDB 시간의 0.78~0.96배가 걸리고(Python의 점수 쿼리에서는 둘이 같습니다), redb는 Rust에서 0.93배와 0.98배가 걸립니다. 열 번을 실행하면 DaruDB가 둘 다 앞서서 둘은 DaruDB 시간의 1.20~1.54배가 걸리고, Realm도 1.04~3.7배가 걸립니다. 키-값 저장소용으로 직접 짠 레코드는 나이와 점수를 정해진 자리에 두므로 그 바이트만 읽고 돌려줄 객체만 디코딩합니다. Realm은 속성마다 값을 모아 두므로 도시 값만 읽고, SQLite의 레코드는 맨 앞에 열의 타입을 늘어놓으므로 한 열을 찾을 때 앞선 값을 읽지 않고 크기만 더합니다. DaruDB의 레코드는 필드마다 id와 타입을 붙여 이름을 바꿔도 비용이 없고, 믿을 수 없는 파일에서 읽은 내용을 엔진이 검사할 수 있게 합니다. 그래서 처음 훑을 때는 레코드마다 검사할 필드 앞의 필드를 하나씩 건너뜁니다. 찾은 자리는 기억해 두므로 두 번째 실행부터는 그 자리에서 바로 읽습니다.</li><li><strong>Dart에서 고칠 때</strong>는 Realm이 DaruDB 시간의 0.50배로 앞섭니다. Node.js에서는 1.11배입니다. Realm은 속성마다 값을 모아 두므로 나이 값 하나만 바꾸지만, DaruDB는 새 나이를 넣어 객체의 레코드를 다시 씁니다.</li><li><strong>Node.js와 Python에서 고유 인덱스로 찾을 때</strong>는 Node.js에서 SQLite가 DaruDB 시간의 0.89배, Python에서 LMDB가 0.96배로 앞섭니다. 인덱스에서 이메일의 항목을 찾고 그 키로 객체를 다시 찾는 두 번의 조회가 들고, 레코드로 그 언어의 객체를 만드는 데도 시간이 듭니다. JavaScript에서는 5분의 1입니다.</li></ul><h2 id="복잡한-스위트" tabindex="-1">복잡한 스위트 <a class="header-anchor" href="#복잡한-스위트" aria-label="Permalink to &quot;복잡한 스위트&quot;">​</a></h2><p>두 번째 스위트는 컬렉션이 여럿인 애플리케이션을 잽니다. 서로 링크로 이어진 컬렉션 셋에 객체가 모두 401,000개 있고, 쿼리는 링크와 목록, 여러 인덱스를 한꺼번에 거칩니다. 쿼리 언어가 있는 저장소만 이 스위트를 돌립니다. DaruDB와 SQLite, 그리고 Node.js와 Dart에서는 Realm입니다. 키-값 저장소에는 플래너가 없어서, 쿼리마다 직접 짠 코드를 재면 저장소가 아니라 그 코드를 재게 됩니다.</p><p>이 표는 위의 표와 같은 실행에서 나왔고, 언어마다 첫 스위트를 돈 러너에서 이어서 잰 것입니다. 그래서 Rust, Dart, Python은 EPYC 9V45 러너에서, Node.js는 EPYC 7763 러너에서 돌았습니다. 한 패스가 더 오래 걸려서 칸마다 다섯 패스의 중앙값입니다.</p>',18)),r(a,{suite:"complex"}),t[4]||(t[4]=d(`<h3 id="이-스위트가-재는-것" tabindex="-1">이 스위트가 재는 것 <a class="header-anchor" href="#이-스위트가-재는-것" aria-label="Permalink to &quot;이 스위트가 재는 것&quot;">​</a></h3><table tabindex="0"><thead><tr><th>컬렉션</th><th>객체 수</th><th>필드</th></tr></thead><tbody><tr><td>조직</td><td>1,000</td><td>키인 코드, 이름, 인덱스를 둔 종류와 국가, 설립 연도</td></tr><tr><td>사람</td><td>100,000</td><td>이름, 고유 인덱스를 둔 이메일, 인덱스를 둔 나이와 국가와 가입일, 내장 객체인 주소, 점수, 활성 여부, 인덱스를 둔 조직 링크, 인덱스를 둔 태그 목록(한 개에서 세 개)</td></tr><tr><td>글</td><td>300,000</td><td>인덱스를 둔 작성자 링크, 제목, 열두 단어로 된 본문, 인덱스를 둔 좋아요 수와 언어와 작성일, 고정 여부, 인덱스를 둔 태그 목록(두 개까지)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>작업</th><th>하는 일</th></tr></thead><tbody><tr><td>객체 401,000개 적재, 트랜잭션마다 10,000개</td><td>세 컬렉션을 채우며, 커밋마다 디스크를 기다립니다. 시간은 객체 하나당입니다</td></tr><tr><td>사람 한 명과 그 조직, 최신 게시글 5개</td><td>키로 찾고, 링크를 따라가고, 글의 작성자 인덱스로 찾기를 10,000번 합니다</td></tr><tr><td>인덱스 둘에 걸친 조건 셋, 정렬 후 50개</td><td>열 살 폭의 나이, 국가 하나, 활성. 점수 내림차순으로</td></tr><tr><td>인덱스 둘에 걸친 OR로 개수 세기</td><td>두 국가의 사람, 또는 78세 이상인 사람</td></tr><tr><td>어떤 글로 시작하는 이름</td><td>이름이 <code>person</code>과 1,000 미만의 수로 시작하는 사람. 인덱스가 없는 필드입니다</td></tr><tr><td>인덱스 순서 깊숙한 곳의 50개 한 페이지</td><td>가입한 순서로 최대 98,703명을 건너뛴 뒤의 50명</td></tr><tr><td>링크 하나 건너</td><td>작성자가 한 국가에 사는, 좋아요 900개 이상인 최신 글 20개</td></tr><tr><td>링크 둘 건너</td><td>작성자의 조직이 한 종류인, 한 언어로 쓴 글의 개수</td></tr><tr><td>리스트 안의 태그, 다른 인덱스로 정렬</td><td>태그 하나가 붙은 글 가운데 좋아요가 가장 많은 20개</td></tr><tr><td>본문에 구절이 든 게시글 개수</td><td>글 300,000개의 본문에서 이어진 두 단어를 인덱스 없이 찾습니다</td></tr><tr><td>인덱스 둘에 걸친 조건으로 개수 세기</td><td>한 언어로 쓴, 좋아요 500개 이상인 글</td></tr><tr><td>쿼리로 찾은 사람 고치기</td><td>네 국가에 사는 사람 약 20,000명의 나이에 한 살을 더하는 트랜잭션 하나. 시간은 한 사람당입니다</td></tr><tr><td>사람 1,000명과 그 게시글 지우기</td><td>트랜잭션 하나로. 시간은 한 사람당입니다</td></tr></tbody></table><p>저장소마다 애플리케이션이 쓰는 방식대로 쿼리를 씁니다. DaruDB는 쿼리 언어로 쓰고 한 번만 준비하며, SQLite는 SQL로 쓰되 링크는 조인이나 서브쿼리로, 목록은 태그 테이블로 둡니다. Realm은 쿼리 언어로 쓰고, 링크에는 인덱스를 둘 수 없어서 사람의 글은 백링크로 찾습니다. SQL의 갱신은 <code>UPDATE</code> 문 하나이고, DaruDB와 Realm은 사람을 찾아 하나씩 고칩니다. 모든 행은 찾은 결과를 요약해 비교하고, 위의 스위트처럼 저장소끼리 결과가 다르면 그 실행은 실패합니다.</p><h3 id="복잡한-스위트에서-darudb가-뒤지는-곳과-이유" tabindex="-1">복잡한 스위트에서 DaruDB가 뒤지는 곳과 이유 <a class="header-anchor" href="#복잡한-스위트에서-darudb가-뒤지는-곳과-이유" aria-label="Permalink to &quot;복잡한 스위트에서 DaruDB가 뒤지는 곳과 이유&quot;">​</a></h3><p>DaruDB는 갱신을 뺀 모든 행에서 SQLite를 앞섭니다. 갱신에는 SQLite가 Python, Node.js, Dart에서 DaruDB 시간의 0.68~0.86배가 걸리고, Rust에서는 둘이 비슷합니다. Realm은 Node.js에서 네 행, Dart에서 세 행에서 앞섭니다.</p><ul><li><strong>본문의 구절로, 그리고 인덱스 둘에 걸친 조건으로 글을 세기.</strong> Realm은 Node.js에서 DaruDB 시간의 0.44배와 0.68배, Dart에서 0.53배와 0.69배가 걸립니다. Realm은 속성마다 값을 모아 두므로 본문만, 또는 언어와 좋아요 수만 읽고, 객체를 만들지 않고 셉니다. DaruDB는 글마다 레코드를 읽어 그 안에서 본문을 찾는데, 글 300,000개의 레코드는 32 MiB인 페이지 캐시에 다 들어가지 않아서 셀 때마다 파일에서 다시 읽습니다. Apple M1 Max에서 파일이 다 들어가는 캐시를 주면 절반의 시간에 셌습니다. 두 조건으로 셀 때는 한 조건의 인덱스에서 키를 모은 뒤 다른 조건의 인덱스를 훑으며 그 안에 든 키만 남깁니다.</li><li><strong>쿼리로 찾은 사람 고치기.</strong> Realm은 Node.js에서 DaruDB 시간의 0.66배가 걸리고 Dart에서는 1.14배가 걸리며, SQLite는 Rust 밖에서 0.68~0.86배가 걸립니다. Realm은 나이를 모아 둔 곳의 값 하나만 바꾸고, SQLite는 문장 하나로 엔진 안에서 모든 행을 바꿉니다. DaruDB는 국가 인덱스로 사람을 찾은 뒤 사람마다 레코드를 제자리에서 고치고 나이 인덱스 항목도 바꾸며, 한 사람에 6.3~9.5µs가 걸립니다.</li><li><strong>Dart에서 링크를 건너 찾는 글.</strong> Realm은 Dart에서 DaruDB 시간의 0.94배가 걸리지만, 찾은 글마다 JavaScript 객체를 만드는 비용이 더 드는 Node.js에서는 1.61배가 걸립니다. Realm은 좋아요 수와 작성자마다의 국가를 모아 둔 값에서 검사합니다. DaruDB는 인덱스에서 그 국가 사람들의 키를 모으고, 작성자 인덱스로 그들의 글을 따라가 좋아요 조건과 맞춘 다음, 작성일 인덱스를 훑어 최신 글을 고릅니다.</li><li><strong>Node.js에서 사람과 그 글을 지우기.</strong> Realm은 EPYC 7763 러너에서 돈 Node.js에서 DaruDB 시간의 0.84배가 걸리고, EPYC 9V45 러너에서 돈 Dart에서는 1.46배가 걸립니다. DaruDB는 글마다 레코드와 인덱스 다섯 개의 항목을 지우고, 커밋에서 바꾼 페이지를 동기화하는데 그 페이지는 파일 곳곳에 흩어져 있습니다. 위의 동기 커밋 행에서 보듯 EPYC 7763 러너는 흩어진 페이지를 더 느리게 동기화합니다.</li></ul><h2 id="직접-실행하기" tabindex="-1">직접 실행하기 <a class="header-anchor" href="#직접-실행하기" aria-label="Permalink to &quot;직접 실행하기&quot;">​</a></h2><p>하네스는 저장소의 <a href="https://github.com/jooy2/darudb/tree/main/bench" target="_blank" rel="noreferrer"><code>bench/</code></a>에 있고, README에 모든 설정을 적었습니다. <code>run-benchmarks</code> 워크플로가 GitHub 호스트 러너에서 하네스를 돌리고, 이 페이지에 실을 결과로 풀 리퀘스트를 엽니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/rust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/run.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/results/rust.json</span></span></code></pre></div><p>복잡한 스위트는 <code>--suite complex</code>로 돌립니다: <code>node bench/run.mjs rust --suite complex --runs 9 --out bench/results/rust-complex.json</code>.</p>`,11))])}const g=s(D,[["render",h]]);export{b as __pageData,g as default};
